// Add swagger
        builder.Services.AddControllers();
        builder.Services.AddEndpointsApiExplorer();
        builder.Services.AddSwaggerGen();
        builder.Services.AddSwaggerGen(options =>
        {
            // include the generated documentaion for Swagger to display in the endpoints browser.
            var xmlFile = $"{System.Reflection.Assembly.GetExecutingAssembly().GetName().Name}.xml";
            var xmlPath = Path.Combine(AppContext.BaseDirectory, xmlFile);

            // Tell Swagger to use it
            options.IncludeXmlComments(xmlPath);
        });
        var app = builder.Build();
        app.UseForwardedHeaders(new ForwardedHeadersOptions
        {
            ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto
        });

        // Configure the HTTP request pipeline.
        if (app.Environment.IsDevelopment())
        {
            app.UseMigrationsEndPoint();
        }
        else
        {
            app.UseExceptionHandler("/Error");
            // The default HSTS value is 30 days. You may want to change this for production scenarios, see https://aka.ms/aspnetcore-hsts.
            app.UseHsts();
        }

        // swagger
        if (Globals.EnableSwagger)
        {
            app.UseSwagger();
            app.UseSwaggerUI(); // Enables the interactive UI at /swagger
        }

        app.UseHttpsRedirection();
        app.UseRouting();
        app.UseStaticFiles();

        // mirror wwwroot under /
        if (Globals.PublicBaseUrl != "/")
        {
            Bovis.Logging.Logger.Default.LogInformation("BC7F8231CC5I Serving public files from {PublicBaseUrl}", Globals.PublicBaseUrl);
            app.UseStaticFiles(new StaticFileOptions
            {
                FileProvider = new PhysicalFileProvider(
                    Path.Combine(Directory.GetCurrentDirectory(), "wwwroot")),
                RequestPath = Globals.PublicBaseUrl
            });
        }
        app.UseRouting();
        // Enable CORS generally. Endpoints must declare a EnableCors Attribute with the policy name to allow CORS requests.
        app.UseCors();
        app.UseAuthorization();

        app.MapControllers();
        app.MapBlazorHub();
        app.MapFallbackToPage("/_Host");


        app.Run();

    }
